/// <summary>
/// PurchFormletterParmDataInvoice extension
/// </summary>
[ExtensionOf(classStr(PurchFormletterParmDataInvoice))]
final class METPurchFormletterParmDataInvoice_Extension
{
    public DocumentDate metDocumentDate;

}

Method.Source:
    /// <summary>
    /// CoC extension to initialise invoice date from the packing slip if the parameter to default is enabled
    /// </summary>
    /// <param name = "_parmTable">The <c>VendDocumentTableMap</c>.</param>
    /// <param name = "_purchLine">The purchase line.</param>
    /// <param name = "_purchTable">The purchase header.</param>
    /// <param name = "_tableRefId">The vendor invoice table reference.</param>
    /// <param name = "_hold">Hold on the vendor invoice.</param>
    /// <param name = "_notApproved">Is vendor invoice approved.</param>
    /// <param name = "_purchSummaryFormLetterId">The invoice number.</param>
    /// <param name = "_postingProfile">Vendor posting profile.</param>
    /// <param name = "_inventProfileType">Inventory profile type.</param>
    /// <returns>The initialized <c>VendDocumentTableMap</c>.</returns>
    protected VendDocumentTableMap initializeParmTable(
        VendDocumentTableMap  _parmTable,
        PurchLine             _purchLine,
        PurchTable            _purchTable,
        TradeLineRefId        _tableRefId,
        boolean               _hold,
        boolean               _notApproved,
        Num                   _purchSummaryFormLetterId,
        VendPostingProfile    _postingProfile,
        InventProfileType_RU  _inventProfileType
       )
    {
        VendDocumentTableMap parmTable = next initializeParmTable(_parmTable, _purchLine, _purchTable, _tableRefId, 
                                                                    _hold, _notApproved, _purchSummaryFormLetterId, _postingProfile, 
                                                                    _inventProfileType);

        if(VendParameters::find().METDefaultInvDate)
        {
            if(this.parmMETDocumentDate())
            {
                parmTable.DocumentDate = this.parmMETDocumentDate();
            }
            else
            {
                VendPackingSlipJour     vendPackingSlipJour;
                VendPackingSlipTrans    vendPackingSlipTrans;

                select firstonly DeliveryDate from vendPackingSlipJour
                        order by DeliveryDate asc
                        where vendPackingSlipJour.PurchId == _purchTable.PurchId
                    exists join vendPackingSlipTrans
                        where   vendPackingSlipTrans.VendPackingSlipJour == vendPackingSlipJour.RecId && 
                                !vendPackingSlipTrans.FullyMatched;

                if(vendPackingSlipJour)
                {
                    parmTable.DocumentDate = vendPackingSlipJour.DeliveryDate;
                }
            }
        }

        return parmTable;
    }

    /// <summary>
    /// MET method to initialise the document date from the receipts
    /// </summary>
    /// <param name = "_purchLine"></param>
    /// <param name = "_vendPackingSlipTrans"></param>
    /// <returns></returns>
    protected VendPackingSlipTrans initVendPackingSlipTrans(PurchLine _purchLine, VendPackingSlipTrans _vendPackingSlipTrans)
    {
        _vendPackingSlipTrans = next initVendPackingSlipTrans(_purchLine, _vendPackingSlipTrans);

        if(this.parmMETDocumentDate())
        {
            if(_vendPackingSlipTrans.vendPackingslipJour().DeliveryDate < this.parmMETDocumentDate())
            {
                this.parmMETDocumentDate(_vendPackingSlipTrans.vendPackingslipJour().DeliveryDate);
            }
        }
        else
        {
            this.parmMETDocumentDate(_vendPackingSlipTrans.vendPackingslipJour().DeliveryDate);
        }

        return _vendPackingSlipTrans;
    }

/// <summary>
/// parm the document date from the receipts
/// </summary>
/// <param name = "_documentDate"></param>
/// <returns></returns>
public DocumentDate parmMETDocumentDate(DocumentDate _documentDate = metDocumentDate)
{
    metDocumentDate = _documentDate;
    return metDocumentDate;
}
